'use strict';
const A='/assets/';
const products=[
{id:'grid-desk',name:'Grid Desk',job:'Queue changes',headline:'Know what changed. Keep the source.',desc:'Monitor dated queue revisions and turn each material change into a cited event brief.',output:'Cited event brief',price:'$600 / month / team',visual:'timeline',inputs:'Fixed public queue snapshots, source-defined fields and retrieval dates.',steps:['Compare dated snapshots','Separate material changes from noise','Attach source rows and alternative explanations'],boundary:'A source-list change is not study priority, available capacity or utility approval.'},
{id:'grid-review',name:'Grid Review',job:'Site evidence',headline:'Two sites. A clearer view of what is unknown.',desc:'Put queue context, available constraint evidence, study assumptions and missing information side by side.',output:'Two-site evidence pack',price:'$4,000 / two-site assessment',visual:'compare',inputs:'Public queue context, authorized redacted study excerpts and available constraint evidence.',steps:['Align two previously screened sites','Expose missing or conflicting evidence','Prepare specific questions for an engineer'],boundary:'Screening evidence is not a feasibility verdict, available-MW guarantee or interconnection approval.'},
{id:'grid-proof',name:'Grid Proof',job:'Application preflight',headline:'Find the missing piece before the next handoff.',desc:'Compare application materials against a configured, dated requirement set and surface exceptions.',output:'Missing-items checklist',price:'$1,500 / application',visual:'docs',inputs:'Mock redacted application documents and an explicitly configured requirement set.',steps:['Select a loaded rule example','Match documents to requirements','Review missing, expired or conflicting material'],boundary:'Completeness suggestions do not establish tariff compliance or guarantee utility acceptance.'},
{id:'grid-signal',name:'Grid Signal',job:'Study comparison',headline:'Compare the assumptions behind each scenario.',desc:'Review supplied study scenarios in one workspace, with source links and an explicit engineer decision.',output:'Engineer review workspace',price:'$900 / month / team',visual:'source',inputs:'Authorized supplied study summaries, scenario assumptions and named reviewers.',steps:['Align supplied scenarios','Keep assumptions and dates visible','Record engineer review and reservations'],boundary:'The workspace does not run an authoritative power-system study or replace accredited engineering.'},
{id:'grid-report',name:'Grid Report',job:'Milestone tracking',headline:'Keep the next milestone in view.',desc:'Track post-submission milestones, open questions and portfolio exposure with a named owner and next action.',output:'Portfolio exposure record',price:'$1,200 / month',visual:'pilot',inputs:'Submitted-project event histories, milestone evidence and portfolio owner assignments.',steps:['Follow source-linked milestones','Surface delayed or uncertain next steps','Preserve owners, dates and open questions'],boundary:'Dates and exposure are reported evidence, not guaranteed schedules, cost forecasts or approval outcomes.'}
];
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const arrow=()=>'<span class="arrow" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none"><path d="M4 12h15m-6-6 6 6-6 6" stroke="currentColor" stroke-width="1.4" stroke-linecap="round" stroke-linejoin="round"/></svg></span>';
const link=(url,label,secondary=false)=>`<a class="button ${secondary?'secondary':'reveal-arrow'}" href="${url}"><span class="button-label">${label}</span>${arrow()}</a>`;
const kick=t=>`<div class="kicker">${t}</div>`;
const demoBadge=()=>'<span class="badge">DEMO · SYNTHETIC DATA</span>';
const reveal=(content,cls='')=>`<div class="reveal ${cls}">${content}</div>`;
const trace=()=>'<svg class="trace" viewBox="0 0 1000 500" preserveAspectRatio="none" aria-hidden="true"><path pathLength="1200" d="M400 0V80Q400 120 460 120H620Q670 120 670 170V340Q670 390 740 390H850Q900 390 900 440V500"/></svg>';
function menuArtifact(id){if(id==='grid-desk')return `<div class="menu-art queue-mini"><span class="mini-label">EXPECTED STUDY / SYN-101</span><div><span>15 Dec</span><i>→</i><strong>12 Jan</strong></div><div class="mini-track"><i></i><b></b></div><small>Source revision · 19 Oct 2026</small></div>`;if(id==='grid-review')return `<div class="menu-art sites-mini"><div class="mini-sites-art"><div class="site-image"></div><div class="site-image solar"></div></div><div><span>Storage</span><span>Solar</span></div><small>Two sites · evidence gaps retained</small></div>`;if(id==='grid-proof')return `<div class="menu-art proof-mini"><span class="mini-label">APPLICATION EVIDENCE</span>${[['Queue extract','✓'],['Study summary','✓'],['Requirement set','?']].map(([t,v])=>`<div><span>${t}</span><b>${v}</b></div>`).join('')}<small>Missing item stays visible</small></div>`;if(id==='grid-signal')return `<div class="menu-art signal-mini"><span class="mini-label">SUPPLIED SCENARIOS</span><div><span>Assumption</span><b>A</b><b>B</b></div><div><span>Study date</span><span>Dec</span><span>Jan</span></div><div><span>Capacity</span><b>?</b><b>?</b></div><small>Compare inputs · engineer reviews</small></div>`;return `<div class="menu-art report-mini"><span class="mini-label">NEXT MILESTONES</span><div><span>SYN-101</span><i><b></b></i><small>Review</small></div><div><span>SYN-102</span><i><b></b></i><small>Missing</small></div><small>Evidence · owner · next action</small></div>`}
function productMenu(){return `<div class="mega mega-evidence"><div class="mega-intro"><span class="disclosure">From queue change to engineer review</span><a href="/products">Explore the product suite →</a></div><div class="mega-products">${products.map((p,i)=>`<a class="mega-product" href="/products/${p.id}">${menuArtifact(p.id)}<span class="mega-title"><strong>${p.name}</strong><span>↗</span></span><span class="mega-job">${p.job}</span><p>${p.output}</p></a>`).join('')}</div><div class="mega-foot"><span>Synthetic artifact previews · Five separately scoped proposed products</span><a href="/demo">Open the evidence workbench →</a></div></div>`}
function fundingSection(){return `<section class="funding-section"><div class="wrap"><div class="funding-intro">${kick('Company news / Funding announcement')}<h2>The next chapter.<br>Details to come.</h2><p>Funding information will appear here once it is ready to be announced.</p><a class="text-link" href="/contact">Company enquiries <span>→</span></a></div><div class="funding-details"><div><span class="disclosure">Funding amount</span><h3>To be announced</h3></div><div><span class="disclosure">Investors / VC</span><h3>To be announced</h3></div><p class="note">Announcement placeholder. No funding round or investor participation is confirmed here.</p></div></div></section>`}
function mobileProducts(){return `<details class="mobile-product-group"><summary><span>Products<small>Five proposed modules</small></span><span>+</span></summary><div class="mobile-product-list">${products.map(p=>`<a href="/products/${p.id}">${menuArtifact(p.id)}<span><strong>${p.name}</strong><small>${p.output}</small><i>Explore →</i></span></a>`).join('')}<a class="mobile-all-products" href="/products">Explore all five products →</a></div></details>`}
function header(){return `<header class="site-header"><div class="wrap header-inner"><a class="logo" href="/" aria-label="InterConnectTrack home"><img src="${A}logo-primary.svg" alt="InterConnectTrack" width="230" height="37"></a><nav class="desktop-nav" aria-label="Main"><details class="menu-group"><summary>Products</summary>${productMenu()}</details><a href="/platform">Platform</a><a href="/solutions">Use cases</a><a href="/resources">Resources</a><a href="/pricing">Pricing</a></nav><div class="header-actions"><a href="/sign-in">Sign in</a>${link('/pilot','Request evaluation')}</div><button class="mobile-toggle" aria-expanded="false" aria-controls="mobile-nav" aria-label="Open navigation">☰</button></div><nav class="mobile-nav" id="mobile-nav" aria-label="Mobile">${mobileProducts()}${[['/platform','Platform'],['/solutions','Use cases'],['/resources','Resources'],['/pricing','Pricing'],['/company','Company'],['/demo','Explore synthetic demo'],['/pilot','Request evaluation'],['/sign-in','Sign in']].map(([u,t])=>`<a href="${u}">${t}</a>`).join('')}</nav></header>`}
function footer(){return `<footer class="site-footer"><div class="wrap"><div class="footer-top"><div><a class="logo" href="/"><img src="${A}logo-primary.svg" alt="InterConnectTrack"></a><p>Evidence for the next interconnection decision.</p><span class="disclosure">Research-stage concept</span><div class="social-icons"><button disabled aria-label="LinkedIn"><svg viewBox="0 0 24 24" aria-hidden="true"><path fill="currentColor" d="M5 3a2 2 0 1 0 0 4 2 2 0 0 0 0-4ZM3.5 9H7v12H3.5Zm6 0H13v1.6c.8-1.3 2-2 3.6-2 3.2 0 4.4 2 4.4 5.4v7h-3.5v-6.3c0-1.8-.3-3-2-3s-2.5 1.2-2.5 3V21H9.5Z"/></svg></button><button disabled aria-label="Crunchbase"><svg viewBox="0 0 32 24" aria-hidden="true"><path d="M13 8a6 6 0 1 0 0 8M19 3v15m0-6a5 5 0 1 1 0 3" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round"/></svg></button></div></div>${[
['Products',products.map(p=>['/products/'+p.id,p.name])],['Explore',[['/platform','Platform'],['/solutions','Developer workflows'],['/pricing','Proposed pricing'],['/pilot','Two-site evaluation'],['/demo','Synthetic demo']]],['Evidence',[['/resources','Resources'],['/resources/sample-queue-brief','Sample queue brief'],['/resources/evidence-packet','Evidence packet'],['/methodology','Methodology'],['/data-coverage','Data coverage']]],['Company',[['/company','About'],['/why-interconnecttrack','Why InterConnectTrack'],['/trust','Trust & boundaries'],['/contact','Contact'],['/sign-in','Workspace access']]]].map(([t,links])=>`<div class="footer-col"><h4>${t}</h4>${links.map(([u,n])=>`<a href="${u}">${n}</a>`).join('')}</div>`).join('')}</div><div class="footer-bottom"><span>© 2026 InterConnectTrack · Concept preview · Synthetic examples only</span><span><a href="/legal/privacy">Privacy</a> &nbsp; <a href="/legal/terms">Terms</a> &nbsp; <a href="/legal/cookies">Cookies</a> &nbsp; <a href="/accessibility">Accessibility</a> &nbsp; <a href="/assets/intro-credits.txt">Film credits</a></span></div></div></footer>`}
function timeline(){return `<div class="timeline-visual"><div class="timeline-top"><div><div class="disclosure">Expected study date · SYN-101</div><div class="timeline-date">15 Dec 2026 <i>→</i> 12 Jan 2027</div></div><span class="note">Synthetic revision<br>19 Oct 2026</span></div><div class="timelines">${[false,true].map(newer=>`<div class="timeline"><h4>${newer?'19':'05'} Oct 2026 snapshot</h4><div class="months">${['OCT','NOV','DEC','JAN','FEB','MAR'].map(x=>`<span>${x}</span>`).join('')}</div>${['Expected study','Application','Study evidence','Next milestone'].map((x,i)=>`<div class="gantt-row ${newer&&i===0?'changed':''}"><span>${x}</span><div class="gantt-track"><div class="gantt-bar" style="--start:${[10,27,12,50][i]}%;--length:${i===0?(newer?66:34):[0,40,65,36][i]}%"></div></div></div>`).join('')}</div>`).join('')}</div><div class="timeline-legend"><span>○ Prior source value retained</span><span>● Changed field, not an approval</span></div></div>`}
function documents(){return `<div class="evidence-console motion-panel"><div class="console-heading"><span class="disclosure">Evidence register / SYN-101</span><span class="badge">3 sources</span></div><div class="evidence-ruler"><span>05 OCT</span><span>19 OCT 2026</span><span>REVIEW</span></div>${[['Queue snapshot','Current revision','19 Oct 2026','Expected study date moved to 12 Jan 2027. The prior value remains in the record.','current'],['Study summary','Older evidence','Earlier snapshot','The summary predates the queue revision. It cannot explain the change without further review.','stale'],['Requirement set','Evidence gap','Not configured','No actual tariff rules are loaded. Application completeness cannot be established.','missing']].map(([title,state,date,detail,status],i)=>`<details class="evidence-entry ${status}" ${i===0?'open':''}><summary><span class="entry-index">0${i+1}</span><span><strong>${title}</strong><small>${date}</small></span><span class="entry-state">${state}</span><span class="entry-plus">+</span></summary><div class="entry-detail"><p>${detail}</p><span class="code">${i===0?'QUEUE-SYN-101 · ROW 14':'SYNTHETIC REFERENCE · HUMAN REVIEW'}</span></div></details>`).join('')}<div class="console-foot"><span class="source-dot"></span>Different dates. One traceable record.<span>DEMO</span></div></div>`}
function siteCard(i){return `<article class="site-card"><header><h4>${i?'Mesa Reach Solar':'Cedar Junction Storage'}</h4><span>SYN-10${i+1}</span></header><div class="site-image ${i?'solar':''}" role="img" aria-label="Illustrative ${i?'solar':'battery storage'} site"></div><div class="evidence-rows"><div class="evidence-row"><span>Queue source</span><span>19 Oct 2026 ↗</span></div><div class="evidence-row"><span>Study evidence</span><span>${i?'Document missing':'Older summary'}</span></div><div class="evidence-row"><span>Reviewer state</span><span>Further evidence required</span></div><div class="uncertain"><span aria-hidden="true">△</span><span>${i?'Study material needs to be supplied before comparison.':'Capacity assumption remains unverified. Requires engineer review.'}</span></div></div></article>`}
function comparison(){return `<div class="compare-grid">${siteCard(0)}${siteCard(1)}</div>`}
function packet(){return `<div class="packet-scene packet-console motion-panel" aria-label="Illustrative engineer review packet with unresolved questions"><div class="console-heading"><span class="disclosure">Review packet / 02 sites</span><span class="badge">Synthetic</span></div><div class="packet-layout"><aside class="packet-ledger"><span class="disclosure">Included evidence</span>${[['01','Queue revision','Source retained'],['02','Study summary','Older evidence'],['03','Application','Missing material']].map(([n,t,d])=>`<div class="ledger-item"><span>${n}</span><div>${t}<small>${d}</small></div></div>`).join('')}<div class="ledger-line"></div><span class="note">Uncertainty travels<br>with the packet.</span></aside><div class="packet-sheet"><img class="packet-logo" src="${A}logo-primary.svg" alt="InterConnectTrack"><h3>Project Evidence<br>Packet</h3><p class="note">Cedar Junction + Mesa Reach</p>${[['Case','SYN-101 / SYN-102'],['Snapshot','19 Oct 2026'],['Review','Further evidence required']].map(([a,b])=>`<div class="packet-row"><span>${a}</span><span>${b}</span></div>`).join('')}<details class="packet-reservation"><summary>One unresolved assumption <span>+</span></summary><p>Capacity remains unverified. Obtain appropriate study evidence before interpreting electrical headroom.</p></details><div class="packet-stamp"><b>NOT A GRID STUDY</b><p>Evidence prepared for human review. No interconnection approval.</p></div></div></div><div class="console-foot">DEMO · SYNTHETIC DATA<a href="/resources/evidence-packet">Inspect packet →</a></div></div>`}
function source(){return `<div class="source-doc"><div class="code">FICTIONAL SOURCE / QUEUE-SYN-101 / ROW 14</div><h3>One change.<br>A source you can inspect.</h3><div class="observed">Expected study date<br>15 Dec 2026 → 12 Jan 2027</div><div class="packet-row"><span>Snapshot / retrieved</span><span>19 Oct 2026</span></div><div class="packet-row"><span>Prior snapshot</span><span>05 Oct 2026</span></div><blockquote>Observed: the date changed.<br>Not established: cause, capacity or a better project outcome.</blockquote><a class="text-link" href="/demo/cases/SYN-101">Inspect the synthetic record <span>↗</span></a></div>`}
function flow(){return `<div class="record-flow flow-console motion-panel"><div class="console-heading"><span class="disclosure">A connected evidence record</span><span class="badge">SYN-101</span></div><div class="flow-route">${[['01','Source ledger','Dated queue revision','05 → 19 Oct 2026'],['02','Exception','Capacity assumption','Unverified'],['03','Engineer review','Named reviewer','Further evidence required'],['04','Evidence packet','Sources + reservations','Ready to inspect']].map(([n,t,v,d])=>`<a class="route-node" href="${n==='04'?'/resources/evidence-packet':'/demo/cases/SYN-101'}"><span class="route-index">${n}</span><div><small>${t}</small><h4>${v}</h4><span class="note">${d}</span></div><span aria-hidden="true">→</span></a>`).join('')}</div><div class="console-foot">DEMO · SYNTHETIC DATA<span>No external action</span></div></div>`}
function pilotVisual(){return `<div class="pilot-visual">${[0,1].map(i=>`<div class="pilot-file"><div class="disclosure">Previously screened</div><h4>Site ${i?'B':'A'}</h4><div class="site-image ${i?'solar':''}"></div><span class="note">Historical assessment</span></div>`).join('')}<div class="pilot-checklist">${['Named interconnection engineer','Authorized redacted evidence','Baseline + evaluation rubric','Conditional paid statement of work'].map((x,i)=>`<div><span>0${i+1} / ${x}</span><span>○ Required</span></div>`).join('')}</div></div>`}
const visual=t=>({timeline,docs:documents,compare:comparison,packet,source,flow,pilot:pilotVisual}[t]||documents)();
function productRows(){return `<div class="product-explorer"><div class="product-selectors" aria-label="Explore five proposed products">${products.map((p,i)=>`<button class="product-select" data-product="${i}" aria-pressed="${i===0}"><span class="num">0${i+1}</span><span><strong>${p.name}</strong><small>${p.job}</small></span>${arrow()}</button>`).join('')}</div><div class="product-preview" aria-live="polite">${productPreview(0)}</div></div>`}
function productPreview(i){const p=products[i];return `<div class="product-preview-head"><span class="disclosure">Proposed module / ${p.name}</span><span class="badge">DEMO</span></div>${modulePreview(p.id)}<div class="product-preview-copy"><h3>${p.output}</h3><p>${p.desc}</p><a class="text-link" href="/products/${p.id}">Explore ${p.name} <span>→</span></a></div>`}
function modulePreview(id){if(id==='grid-desk')return `<div class="module-art">${timeline()}</div>`;if(id==='grid-review')return `<div class="module-art mini-sites">${[0,1].map(i=>`<div><div class="site-image ${i?'solar':''}"></div><div class="mini-site-copy"><span class="disclosure">SYN-10${i+1}</span><h4>${i?'Mesa Reach Solar':'Cedar Junction Storage'}</h4><span class="badge warn">${i?'Study missing':'Assumption unverified'}</span></div></div>`).join('')}</div>`;if(id==='grid-proof')return `<div class="module-art">${documents()}</div>`;if(id==='grid-signal')return `<div class="module-art scenario-console motion-panel"><div class="console-heading"><span class="disclosure">Supplied scenario comparison</span><span class="badge">Illustrative</span></div><div class="scenario-table"><div><span>Evidence field</span><strong>Scenario A</strong><strong>Scenario B</strong></div>${[['Queue snapshot','05 Oct','19 Oct'],['Expected study','15 Dec 2026','12 Jan 2027'],['Capacity evidence','Unverified','Unverified'],['Study material','Older summary','Not supplied']].map(row=>`<div>${row.map(t=>`<span>${t}</span>`).join('')}</div>`).join('')}</div><div class="scenario-review"><span class="review-ring">!</span><p>Different assumptions.<br><strong>Engineer review required.</strong></p></div><div class="console-foot">Synthetic supplied inputs · No grid study performed</div></div>`;return `<div class="module-art milestone-console motion-panel"><div class="console-heading"><span class="disclosure">Portfolio / next actions</span><span class="badge">2 sites</span></div>${[['SYN-101','Cedar Junction','Review revised date','12 Jan 2027'],['SYN-102','Mesa Reach','Obtain study material','Date unknown']].map(([id,n,a,d],i)=>`<div class="milestone-item"><div><span class="disclosure">${id}</span><h4>${n}</h4><small>${d}</small></div><div class="milestone-rail"><i></i><i></i><i class="open"></i><i class="open"></i></div><p>${a}<small>Named engineer · next action</small></p></div>`).join('')}<div class="console-foot">DEMO · Fixed illustrative records<span>No live telemetry</span></div></div>`}

const faqs=[['Is this a grid study?','No. InterConnectTrack is a research-stage concept for read-only evidence support. Accredited engineering, utility/ISO studies and approval remain outside its authority.'],['Which regions and rules are supported?','The prototype has one explicitly synthetic example. Real jurisdiction-specific workflows will only be demonstrated after the actual dated rules are loaded and reviewed.'],['What is connected to this demo?','Nothing external. It uses a fixed invented queue event log and mock project records. There is no dispatch, utility writeback or production connector.'],['What would a two-site evaluation need?','Two previously screened sites, authorized redacted queue/study evidence, a named engineer, a historical comparator, a pre-agreed rubric and conditional paid SOW.'],['Are the proposed prices final?','No. Each price is an interview-test hypothesis and a separate scope discussion, not an accepted market rate or active checkout.'],['Who owns the decision?','A named developer-side engineer reviews consequential assumptions. The product does not approve a connection, certify capacity or make physical/control decisions.']];
const faqHtml=()=>`<div class="faq">${faqs.map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('')}</div>`;
function closing(){return `<section class="closing"><img class="closing-landscape" src="/assets/closing-energy-landscape.jpg" alt="" width="1536" height="1024" loading="lazy"><div class="wrap reveal"><img class="closing-mark" src="${A}symbol-primary.svg" alt=""><h2>Bring two sites.<br>Test whether the evidence is useful.</h2><p>A manually assisted evaluation. Your historical assessment. A named engineer. A decision based on what the evidence can support.</p><div class="actions">${link('/pilot','Request a two-site evaluation')}${link('/resources/evidence-packet','View a sample packet',true)}</div><div class="disclosure">Proposed evaluation · No payment collected in this prototype</div></div></section>`}
const storyStates=[['Snapshot','A new date. A new question.','The expected study date moves between two fixed snapshots. Both source values remain visible.','timeline'],['Source','Open the record behind the change.','A source row explains what changed. It does not explain away the older study note or the missing evidence.','source'],['Exception','Make the unknown impossible to miss.','The two sites have different evidence gaps. Neither receives a fabricated capacity score.','compare'],['Packet','Keep the reservations with the record.','The packet carries the observed change, source references, unverified assumption and next action into human review.','packet']];
function story(){return `<section class="story-section line-top" id="story"><div class="wrap"><div class="section-title reveal"><div>${kick('05 / Follow one changed record')}<h2>One case.<br>Four clearer questions.</h2></div><div><button class="button secondary" id="all-states" aria-pressed="false">View all states / pause motion</button><p class="note"><a href="#platform-flow">Skip the story ↓</a></p></div></div><div class="story-layout"><div class="story-notes">${storyStates.map(([n,t,p,v],i)=>`<article id="step-${i}" data-step="${i}"><div class="kicker">0${i+1} / ${n}</div><h2>${t}</h2><p class="muted">${p}</p><div>${demoBadge()}</div><div class="inline-scene">${visual(v)}</div></article>`).join('')}</div><aside class="story-stage" aria-label="Synthetic case storyboard">${demoBadge()}<nav class="story-steps" aria-label="Story states">${storyStates.map(([n],i)=>`<a href="#step-${i}" data-go="${i}" ${i===0?'aria-current="step"':''}>0${i+1} ${n}</a>`).join('')}</nav>${storyStates.map((s,i)=>`<div class="scene" data-scene="${i}" ${i?'hidden':''}>${visual(s[3])}</div>`).join('')}<p class="note" style="margin-top:15px">Scrolling changes the illustration, not a reviewer decision.</p></aside></div></div></section>`}
const usecases=[['Screen sites','Origination → interconnection engineer','Bring two candidate sites into the same evidence frame. Identify the unknowns before deciding where to spend more diligence effort.','grid-review','site-screening'],['Prepare applications','Operator → engineer reviewer','Match the application packet to a configured requirement set. Keep missing and conflicting information visible.','grid-proof','application-review'],['Compare scenarios','Engineer → accountable director','Compare supplied assumptions and record the independent reviewer’s reservations.','grid-signal','application-review'],['Track portfolios','Portfolio manager → named owner','Follow the next milestone with its evidence, uncertainty and accountable next action.','grid-report','portfolio-oversight']];
function usecaseView(i){const u=usecases[i];return `<div><h3>${u[0]}, with a traceable handoff.</h3><p class="muted">${u[2]}</p><a class="text-link" href="/solutions/${u[4]}">Explore this workflow <span>↗</span></a></div><div class="usecase-visual">${modulePreview(u[3])}<div class="handoff"><span>${u[1]}</span><span>Human review</span></div></div>`}
function scrollJourney(kind){const product=kind==='products',items=product?products:usecases;return `<div class="scroll-journey ${product?'product-journey':'workflow-journey'}" data-journey="${kind}" style="--steps:${items.length}"><div class="journey-pin"><div class="journey-meta"><span class="disclosure">${product?'Five products. One evidence trail.':'Four handoffs. One connected record.'}</span><span class="journey-hint">Scroll to explore ↓</span></div><nav class="journey-nav" aria-label="${product?'Product':'Workflow'} story chapters">${items.map((v,i)=>`<button data-journey-to="${i}" aria-current="${i===0?'step':'false'}"><span>0${i+1}</span><strong>${product?v.name:v[0]}</strong></button>`).join('')}</nav><div class="journey-panels">${items.map((v,i)=>{const id=product?v.id:v[3],title=product?v.output:v[0]+', with a traceable handoff.',desc=product?v.desc:v[2],url=product?'/products/'+v.id:'/solutions/'+v[4];return `<article class="journey-panel" data-chapter="${i}" id="${kind}-chapter-${i}"><div class="journey-copy"><div class="kicker">0${i+1} / ${product?v.job:v[1]}</div><h3>${title}</h3><p>${desc}</p><a class="text-link" href="${url}">${product?'Explore '+v.name:'Explore this workflow'} <span>→</span></a><div class="disclosure">${product?'Proposed module':'Developer workflow'} · Synthetic preview</div></div><div class="journey-art">${modulePreview(id).replaceAll(' open','')}</div></article>`}).join('')}</div><div class="journey-bottom"><span class="journey-counter">01 / 0${items.length}</span><span class="journey-progress"><i></i></span><button class="journey-mode" aria-pressed="false">View all steps</button><a href="#${product?'story':'evaluation'}">Skip section ↓</a></div></div></div>`}
function home(){return `<section class="site-intro" id="site-intro" role="dialog" aria-modal="true" aria-label="InterConnectTrack introduction" hidden><video muted playsinline preload="none" poster="/assets/intro-poster-desktop-v2.jpg" aria-label="Two sites. One evidence trail. Compare site evidence, trace queue changes, and prepare a packet for engineer review."></video><div class="intro-brand"><img src="/assets/logo-primary.svg" alt="InterConnectTrack" width="258" height="52"></div><div class="intro-controls"><button type="button" data-intro-toggle>Pause film</button><button type="button" data-intro-skip>Skip intro <span aria-hidden="true">→</span></button></div><div class="intro-progress" aria-hidden="true"></div></section><section class="hero"><div class="wrap"><div class="hero-copy">${kick('For US renewable & storage developers')}<h1>Every project changes. Keep the evidence connected.</h1><p class="lead">Trace queue changes, compare site evidence and prepare the next engineer review.</p><div class="actions">${link('/demo','Explore the demo')}${link('/pilot','Request evaluation',true)}</div><div class="disclosure">Concept preview · Simulated data</div><button class="intro-watch" type="button" data-intro-replay><span aria-hidden="true">▷</span> Watch the introduction · 16 sec</button></div><div class="hero-art"><img src="${A}terrain.webp" width="1536" height="1024" fetchpriority="high" alt="Original architectural relief of fictional solar, battery storage and substation sites"><div class="hero-callout callout-a">Cedar Junction Storage<small><i class="source-dot"></i>Source revision · 19 Oct 2026</small></div><div class="hero-callout callout-b">Mesa Reach Solar<small><i class="source-dot"></i>Assumption unverified</small></div>${trace()}</div><a class="hero-scroll" href="#change"><span>↓</span>Follow the evidence</a></div></section>
<section class="section mineral" id="change"><div class="wrap split"><div class="reveal">${kick('01 / The change')}<h2>A new date.<br>A new question.</h2><p class="muted">Queue information changes. See the difference, compare the sources and follow the evidence into the next decision.</p><a class="text-link" href="#evidence-gap">Scroll to inspect the source <span>↓</span></a></div>${reveal(timeline())}</div></section>
<section class="section" id="evidence-gap"><div class="wrap split"><div class="reveal">${kick('02 / The evidence gap')}<h2>The dates don’t always tell the same story.</h2><p class="muted">A queue snapshot, an older study note and an incomplete checklist can describe the same project differently. Keep those differences visible.</p><a class="text-link" href="/why-interconnecttrack">Why an evidence record matters <span>↗</span></a></div>${reveal(documents())}</div></section>
<section class="context-band"><div class="wrap context-inner"><div>${kick('Context, with a source')}</div><p>A public queue snapshot is not an ISO study or utility capacity approval. FERC reform and Berkeley Lab queue research describe the wider problem.</p><div class="source-links"><a href="https://www.ferc.gov/interconnection-reform" target="_blank" rel="noopener">FERC ↗</a><a href="https://emp.lbl.gov/queues" target="_blank" rel="noopener">Berkeley Lab ↗</a><a href="/resources/interconnection-process">Read context ↗</a></div></div></section>
<section class="section" id="products"><div class="wrap"><div class="section-title reveal"><div>${kick('04 / Five jobs. Five deliverables.')}<h2>Evidence for each stage<br>of interconnection.</h2></div><a class="text-link" href="/products">Explore all five products <span>↗</span></a></div>${scrollJourney('products')}<p class="note" style="margin-top:20px">Five separately scoped proposed offers. Availability and prices remain evaluation hypotheses.</p></div></section>
${story()}
<section class="section" id="comparison"><div class="wrap split"><div class="reveal">${kick('The review')}<h2>Two sites.<br>One clear view<br>of what is unknown.</h2><p class="muted">Different sources, different evidence, the same questions. Bring site information together and see exactly what still needs a human review.</p><a class="text-link" href="/products/grid-review">Explore Grid Review <span>↗</span></a></div>${reveal(comparison())}</div></section>
<section class="section dark packet-section" id="packet"><div class="wrap split"><div class="reveal">${kick('The packet')}<h2>A decision deserves<br>a traceable record.</h2><p class="muted">Bring the sources, notes and open questions together in one clear packet for the next engineer review.</p><div class="actions"><a class="button light packet-cta" href="/resources/evidence-packet">View sample packet</a></div><p class="note">Human review. Explicit uncertainty.<br>No grid control.</p></div>${reveal(packet())}</div></section>
<section class="section" id="platform-flow"><div class="wrap split"><div class="reveal">${kick('06 / One record across the work')}<h2>Nothing important<br>loses its source.</h2><p class="muted">The case record joins observations, exceptions, reviewer notes and outputs. Each product contributes to the same defensible history.</p><a class="text-link" href="/platform">Explore the platform <span>↗</span></a></div>${reveal(flow())}</div></section>
<section class="section mineral" id="developer-work"><div class="wrap"><div class="section-title">${reveal(`${kick('07 / Built around developer work')}<h2>From the first screen<br>to the next milestone.</h2>`)}</div>${scrollJourney('workflows')}</div></section>
<section class="section authority-section"><div class="wrap split"><div class="reveal">${kick('08 / Clear authority boundaries')}<h2>Review remains<br>with the engineer.</h2><p class="muted">Evidence support has a specific place in the process. It does not replace accredited engineering, utility studies or ISO approval.</p><a class="text-link" href="/trust">See the boundaries <span>↗</span></a></div>${reveal(`<div class="authority"><div><h3>Evidence available</h3><ul><li>Dated source changes</li><li>Missingness and conflicts</li><li>Reviewer questions</li><li>Exportable record</li></ul></div><div class="no-control"><h3>Human authority</h3><ul><li>Engineering decisions</li><li>Study acceptance</li><li>Utility / ISO approval</li><li>No product dispatch</li></ul></div></div>`)}</div></section>
<section class="section mineral" id="evaluation"><div class="wrap split"><div class="reveal">${kick('09 / A useful first test')}<h2>Start with two sites<br>you already screened.</h2><p class="muted">Compare an evidence packet against your historical assessment. Agree on the baseline, evaluator and failure threshold before the work begins.</p><div class="actions">${link('/pilot','Discuss the two-site evaluation')}</div><p class="note">Proposed $4,000 manually assisted assessment.<br>Price test hypothesis. No payment is collected here.</p></div>${reveal(pilotVisual())}</div></section>
<section class="section"><div class="wrap faq-layout"><div>${kick('10 / Before you begin')}<h2>Good questions<br>come first.</h2><div class="question-visual" aria-hidden="true">?</div></div>${faqHtml()}</div></section>${fundingSection()}${closing()}`} 
function pageHero(k,title,desc,vis='',cta='/pilot'){return `<section class="page-hero ${vis?'visual':''}"><div class="wrap"><div class="breadcrumbs"><a href="/">Home</a> / ${k}</div>${vis?'<div class="split equal">':''}<div>${kick(k)}<h1>${title}</h1><p class="lead muted">${desc}</p><div class="actions">${link(cta,cta==='/demo'?'Explore synthetic demo':'Request evaluation')}${link('/resources/evidence-packet','View sample packet',true)}</div><div class="disclosure">Concept preview · Synthetic examples</div></div>${vis?`<div>${visual(vis)}</div></div>`:''}</div></section>`}
function productPage(p){return pageHero(p.name,p.headline,p.desc,p.visual)+`<section class="content-section mineral"><div class="wrap"><div class="section-title"><h2>A specific job.<br>A reviewable output.</h2><span class="badge">Proposed module / ${p.job}</span></div><div class="info-grid">${p.steps.map((s,i)=>`<article class="info-card reveal"><div class="kicker">0${i+1}</div><h3>${s}</h3><p>${[p.inputs,'Observed facts remain separate from interpretation. Missingness and dates travel with the evidence.',p.boundary][i]}</p></article>`).join('')}</div></div></section><section class="section"><div class="wrap split"><div>${kick('Inputs and exceptions')}<h2>Know what the source<br>can support.</h2><p class="muted">${p.inputs}</p><p class="muted">Permission, source cadence, study confidentiality and tariff specificity are separate constraints. A missing input stays missing.</p><a class="text-link" href="/data-coverage">Inspect demo coverage <span>↗</span></a></div>${p.id==='grid-review'?comparison():source()}</div></section><section class="section dark"><div class="wrap split"><div>${kick('The deliverable')}<h2>${p.output}.</h2><p class="muted">Every output retains the source version, input dates, missing evidence, reviewer note and next action.</p><p class="note">${p.boundary}</p><a class="button light" href="/demo">Open the synthetic workflow ↗</a></div>${packet()}</div></section><section class="section"><div class="wrap split"><div>${kick('Scope the evaluation')}<h2>Test usefulness.<br>Keep the claims honest.</h2><p class="price">${p.price}</p><p class="note">Price test hypothesis · separately quoted scope · not checkout</p><p class="muted">Begin with authorized retrospective evidence and a named engineer. Compare against the current workflow before deciding whether to proceed.</p>${link('/pilot','Discuss '+p.name)}</div>${pilotVisual()}</div></section><section class="content-section"><div class="wrap"><h2>Questions before an evaluation.</h2>${faqHtml()}</div></section>${closing()}`}
function pricing(){return pageHero('Proposed pricing','Five offers.<br>Five scope conversations.','Each price is a test hypothesis for interviews and a conditional statement of work. No pricing acceptance, savings guarantee or active checkout is implied.')+`<section class="content-section"><div class="wrap">${products.map(p=>`<div class="pricing-row"><h3><a href="/products/${p.id}">${p.name}</a></h3><div class="price">${p.price}<small>PRICE TEST HYPOTHESIS</small></div><p>${p.output}<br><span class="muted">${p.job}</span></p>${link('/pilot','Discuss scope',true)}</div>`).join('')}</div></section><section class="section mineral"><div class="wrap split"><div><h2>Begin with two previously screened sites.</h2><p>The proposed first evaluation is manually assisted and retrospective. Source coverage, document availability, engineer time and confidentiality shape the final scope.</p>${link('/pilot','View the pilot protocol')}</div>${pilotVisual()}</div></section>`}
function formHtml(type='pilot'){return `<form class="local-form intake-form" data-form-type="${type}" data-intake-step="1" onsubmit="return false" novalidate><div class="form-progress"><span class="form-step-count">01 / 02</span><span class="form-step-name">Your team</span><span>Local preview</span></div><fieldset data-form-step="1"><legend class="sr-only">Your team</legend><div class="form-grid">${[['name','Full name','text'],['email','Work email','email'],['organization','Organization','text']].map(([n,l,t])=>`<div class="field-group"><label for="${n}">${l}</label><input class="field" id="${n}" name="${n}" type="${t}" required autocomplete="${n==='name'?'name':n==='email'?'email':'organization'}" aria-describedby="${n}-error"><span class="field-error" id="${n}-error"></span></div>`).join('')}<div class="field-group"><label for="role">Your role</label><select class="field" id="role" name="role" required aria-describedby="role-error"><option value="">Select role</option><option>Developer interconnection director</option><option>Day-to-day operator / analyst</option><option>Data or integration owner</option><option>Interconnection engineer / consultant</option><option>Utility / ISO — separate enquiry</option></select><span class="field-error" id="role-error"></span></div></div><button class="button" type="submit">Continue to evaluation ${arrow()}</button><p class="form-footnote">No project records needed. Nothing is sent or saved in this prototype.</p></fieldset><fieldset data-form-step="2" hidden><legend class="sr-only">Evaluation scope and consent</legend><div class="form-grid"><div class="field-group"><label for="sites">Previously screened sites</label><select class="field" id="sites" name="sites"><option>Two candidate sites</option><option>More than two — scope discussion</option><option>Not yet available</option></select></div><div class="field-group"><label for="timeframe">Timeframe</label><select class="field" id="timeframe" name="timeframe"><option>Exploring the fit</option><option>Within 1–3 months</option><option>Later</option></select></div><div class="field-group full"><label for="workflow">Workflow / question <span>(optional)</span></label><textarea class="field" id="workflow" name="workflow" rows="2" placeholder="No confidential project records."></textarea></div></div><label class="check"><input type="checkbox" id="followup" name="followup" required aria-describedby="followup-error"><span>I would permit follow-up about this request.</span></label><span class="field-error" id="followup-error"></span><label class="check"><input type="checkbox" name="marketing"><span>Optional: send product research updates.</span></label><div class="intake-actions"><button type="button" class="form-back">← Back</button><button class="button" type="submit">Preview request ${arrow()}</button></div><p class="form-footnote">Local preview only · <a href="/legal/privacy">Privacy</a> · Real records require human security/legal review.</p></fieldset><div class="status" role="status" tabindex="-1"></div></form>`}
function intakeHero(type='pilot'){const isPilot=type==='pilot';return `<section class="intake-hero"><div class="wrap intake-layout"><div class="intake-copy">${kick(isPilot?'Two-site evaluation':type==='contact'?'Contact':'Guided walkthrough')}<h1>${isPilot?'Bring two sites.<br> Start with a conversation.':type==='contact'?'A good decision starts<br>with a good question.':'See the evidence.<br>Follow the review.'}</h1><p>${isPilot?'A manually assisted assessment for US renewable and storage developer teams. Compare the evidence against work you already know.':'Tell us about your team and the workflow you want to explore.'}</p><div class="intake-value"><span>01 / Your team</span><span>02 / Your evaluation</span></div><div class="intake-art"><img src="${A}sites.webp" alt="Illustrative storage and solar sites" loading="eager"></div><p class="note">${isPilot?'Proposed $4,000 two-site assessment · Price test hypothesis.':'A focused conversation about developer-side interconnection.'}<br>No payment or confidential records collected.</p></div><div class="intake-card"><span class="disclosure">${isPilot?'Request evaluation':'Start a conversation'}</span><h2>Let’s understand the fit.</h2><p class="intake-card-note">A few details about your team.</p>${formHtml(type)}</div></div></section>`}
function accessPage(help=false){return `<section class="access-page"><div class="wrap access-layout"><div class="access-copy">${kick('InterConnectTrack / Workspace')}<h1>Your evidence.<br> Ready for review.</h1><p>A considered space for sources, assumptions and the next engineer decision.</p><div class="access-art"><img src="${A}terrain.webp" alt="Illustrative energy infrastructure landscape"></div><div class="access-caption"><span>Sources connected</span><span>Human review retained</span></div></div><div class="access-card"><img class="access-symbol" src="${A}symbol-primary.svg" alt=""><span class="disclosure">Workspace access</span><h2>${help?'Find your workspace.':'Welcome back.'}</h2><p class="muted">${help?'Preview an access request for your team.':'Continue to your team’s evidence workspace.'}</p><form class="access-form" onsubmit="return false" novalidate><label for="access-email">Work email</label><input class="field" type="email" id="access-email" name="email" required autocomplete="email" aria-describedby="access-error"><span class="field-error" id="access-error"></span><button class="button" type="submit">Preview email sign-in ${arrow()}</button><div class="status" role="status"></div></form><p class="form-footnote">Authentication is not connected. No sign-in email is sent and no credentials are stored.</p><div class="access-divider"><span>Explore without signing in</span></div>${link('/demo','Open synthetic workspace',true)}<div class="access-links"><a href="/access-help">Access help</a><a href="/contact">Contact</a></div></div></div></section>`}
function pilotPage(){return intakeHero('pilot')+`<section class="content-section"><div class="wrap"><div class="info-grid">${[['01 / Qualify','Confirm the developer-side buyer, operator, data owner and engineer. Utility-side demand is evaluated separately.'],['02 / Obtain permission','Agree procurement, legal and data permissions before using redacted historical queue or study evidence.'],['03 / Compare and decide','Pre-register the comparator, evaluator, observation window and failure threshold in a conditional paid SOW.']].map(([h,p])=>`<article class="info-card"><h3>${h}</h3><p>${p}</p></article>`).join('')}</div><h3>Proposed scorecard</h3><div class="table-scroll"><table><thead><tr><th>Measure</th><th>Comparison</th><th>Decision boundary</th></tr></thead><tbody><tr><td>Engineer-rated usefulness</td><td>Packet versus prior assessment</td><td>Threshold agreed before evaluation</td></tr><tr><td>Material changes correctly sourced</td><td>Independently checked event log</td><td>No unsourced conclusion presented as authority</td></tr><tr><td>Commercial commitment</td><td>Distinct qualified buyer → paid SOW</td><td>Waitlist and traffic alone do not validate demand</td></tr></tbody></table></div><p class="note">Proposed first test: two sites each with three developers. This is a recruitment target, not achieved participation.</p></div></section><section class="section mineral"><div class="wrap split"><div><h2>Request the<br>scope conversation.</h2><p class="muted">Proposed assessment: $4,000 for two sites, subject to a separate scope and permission review. This is a price test hypothesis.</p><p>Proceed beyond the demo only when authorized evidence, a historical comparator, a named engineer and a signed conditional paid assessment are in place.</p><p class="note">Pause if permission, engineering review or historical comparison is unavailable.</p></div>${pilotVisual()}</div></section>`}
const resources=[['sample-queue-brief','A queue change, with its source.','Observed change, alternative explanation and reviewer next action.','timeline'],['evidence-packet','The record behind a decision.','A synthetic packet with dates, evidence gaps and reviewer reservations.','packet'],['interconnection-process','Screening is not study authority.','A practical developer-side explanation of the workflow and its boundaries.','flow']];
function resourcesPage(){return pageHero('Resources','Inspect the evidence.<br>Ask better questions.','Three useful starting points for understanding the proposed workflow. Examples are synthetic; research sources provide context only.')+`<section class="content-section"><div class="wrap info-grid">${resources.map(([id,t,d,v])=>`<article class="info-card"><img src="${A}diagram-${v==='timeline'?'grid-desk':v==='packet'?'grid-review':'grid-signal'}.svg" alt=""><h3>${t}</h3><p>${d}</p><a class="text-link" href="/resources/${id}">Read the artifact <span>↗</span></a></article>`).join('')}</div></section>`}
function packetPage(){return pageHero('Sample evidence packet','A record that keeps<br>its reservations.','An ungated synthetic review packet. It preserves the source change, dates, missingness, analyst interpretation and explicit reviewer boundary.','packet','/demo')+`<section class="content-section"><div class="wrap"><div class="print-packet">${packetContent()}</div><div class="actions"><button class="button" data-export="packet">Download synthetic packet ↓</button>${link('/demo/packet','Open packet workbench',true)}</div></div></section>`}
function packetContent(reviewed=false,note='Obtain appropriate study evidence before interpreting capacity.'){return `<div class="disclosure">DEMO · SYNTHETIC DATA · NOT A GRID STUDY</div><h2>Project Evidence Packet</h2><p>SYN-101 Cedar Junction Storage + SYN-102 Mesa Reach Solar · As-of 20 Oct 2026</p>${[['Observed change','Expected study date: 15 Dec 2026 → 12 Jan 2027'],['Source','QUEUE-SYN-101 · row 14 · snapshots 05 and 19 Oct 2026'],['Known inputs','Synthetic queue extracts and an older mock study summary'],['Missing evidence','SYN-102 study material; evidence supporting any capacity conclusion'],['Alternative explanation','A source record or cohort changed without establishing electrical headroom'],['Reviewer state',reviewed?'Assumption marked unverified — local demo action':'Further evidence required — illustrative state'],['Reviewer note',esc(note)],['Next action','Obtain permissioned study evidence for independent engineer review']].map(([a,b])=>`<div class="packet-row"><strong>${a}</strong><span>${b}</span></div>`).join('')}<p class="note" style="margin-top:25px">This packet does not constitute a grid study, engineering certification, capacity guarantee, utility approval or dispatch instruction. All identities, cases and source rows are invented.</p>`}
function editorial(k,title,desc,vis,sections){return pageHero(k,title,desc,vis)+sections.map(([h,p,items],i)=>`<section class="content-section ${i%2?'mineral':''}"><div class="wrap ${items?'split':''}"><div class="prose"><h2>${h}</h2>${p.split('\n').map(t=>`<p>${t}</p>`).join('')}</div>${items?`<div>${items}</div>`:''}</div></section>`).join('')}
function solutionPage(slug){const spec=slug==='site-screening'?['Site screening','Before more diligence,<br>align the evidence.','Origination teams and interconnection engineers need to compare two sites without hiding different evidence gaps.','compare',products[1]]:slug==='application-review'?['Application review','Prepare the next<br>engineering handoff.','Operators and engineers need to see missing application material and compare supplied study assumptions.','docs',products[2]]:['Portfolio oversight','Keep milestones tied<br>to an owner.','Interconnection directors and portfolio managers need a dated record of next actions, evidence gaps and exposure.','timeline',products[4]];return editorial(spec[0],spec[1],spec[2],spec[3],[['The handoff',`Inputs stay attached to a named source, date and owner. ${spec[4].inputs}`,flow()],['The proposed workflow',spec[4].steps.join('\n'),`${modulePreview(spec[4].id)}`],['The review boundary',spec[4].boundary,`${link('/products/'+spec[4].id,'Explore '+spec[4].name)}`]])+closing()}
const cases=Array.from({length:10},(_,i)=>({id:'SYN-'+(101+i),name:['Cedar Junction Storage','Mesa Reach Solar','East Basin Storage','Pine Hollow Solar','Westfield Storage','Juniper Solar','Stone Creek Storage','North Ridge Solar','Willow Bend Storage','Canyon Reach Solar'][i],status:['Needs review','Study missing','Pending','Blocked','Reviewed','Pending','Rejected inference','Pending','Blocked','Completed review'][i]}));
let selected='SYN-101',demoTab='evidence',reviewed=false,reviewNote='';
function demoPage(){return `<div class="demo-shell"><div class="demo-top"><div>${demoBadge()}<h1 style="margin-top:10px">Project evidence workbench</h1></div><div class="demo-actions"><a class="button secondary" href="/demo/pilot">Pilot account</a><button class="button secondary" id="reset-demo">Reset demo</button><button class="button" data-export="packet">Export packet ↓</button></div></div><p class="note">Fixed fictional records · No live integrations, control or external submissions · Jurisdiction: synthetic example only</p><div class="demo-grid"><aside class="case-list"><h3>Portfolio / 10 cases</h3><label class="note" for="case-filter">Filter status</label><select class="field" id="case-filter" style="font-size:12px;margin:8px 0"><option value="all">All 10 records</option><option>Needs review</option><option>Study missing</option><option>Pending</option><option>Blocked</option><option>Reviewed</option><option>Rejected inference</option><option>Completed review</option></select><p class="note" id="case-count" role="status">10 records · 2 blocked · 3 pending</p>${cases.map(c=>`<button class="case-item" data-case="${c.id}" ${c.id===selected?'aria-current="true"':''}><small>${c.id} · DEMO</small>${c.name}<small>${c.status}</small></button>`).join('')}</aside><section class="case-detail" aria-label="Selected case"><div id="case-heading"></div><div class="demo-tabs" role="tablist" aria-label="Case views">${['evidence','comparison','review','packet'].map(t=>`<button role="tab" data-demo-tab="${t}" id="demo-tab-${t}" aria-controls="demo-body" aria-selected="${demoTab===t}">${t[0].toUpperCase()+t.slice(1)}</button>`).join('')}</div><div id="demo-body" class="demo-body" role="tabpanel" aria-labelledby="demo-tab-${demoTab}"></div></section><aside class="source-pane" id="source-pane"></aside></div><p class="note" style="margin-top:20px">Scrolling never changes a reviewer decision. An explicit local action is required. Exports retain every demo label and unresolved item.</p></div><dialog id="packet-dialog"><button class="dialog-close" aria-label="Close packet preview">×</button><div class="print-packet" id="dialog-content"></div><button class="button" data-export="packet">Download synthetic packet ↓</button></dialog>`}
function updateDemo(){const c=cases.find(c=>c.id===selected);document.getElementById('case-heading').innerHTML=`<div class="disclosure">${c.id} / DEMO</div><h2>${c.name}</h2><p class="note">Owner: Riley Chen · fictional operator · As-of 20 Oct 2026</p>`;document.querySelectorAll('[data-case]').forEach(b=>b.toggleAttribute('aria-current',b.dataset.case===selected));document.querySelectorAll('[data-demo-tab]').forEach(b=>b.setAttribute('aria-selected',String(b.dataset.demoTab===demoTab)));const body=document.getElementById('demo-body');body.setAttribute('aria-labelledby','demo-tab-'+demoTab);if(selected!=='SYN-101'&&selected!=='SYN-102'){body.innerHTML=`<div class="empty-state"><h3>${c.status}</h3><p>This synthetic portfolio row illustrates an additional case state. Detailed evidence is available for SYN-101 and SYN-102.</p><button class="button secondary" data-select-primary>Open the two-site case</button></div>`;}else if(demoTab==='evidence'){body.innerHTML=selected==='SYN-101'?timeline()+`<div class="source-doc" style="margin-top:24px"><div class="code">QUEUE-SYN-101 / ROW 14</div><p>Synthetic source-list position: 14 → 12.</p><p class="note">This is not study priority or available capacity. Ordinal position is meaningful only when a real source defines it.</p><button class="button secondary" data-inspect-source>Inspect source reference</button></div>`:`${siteCard(1)}<div class="uncertain">△ Study material missing. No capacity conclusion can be supported.</div>`;}else if(demoTab==='comparison'){body.innerHTML=comparison();}else if(demoTab==='review'){body.innerHTML=`<h3>Does queue movement establish available capacity?</h3><span class="badge warn">${reviewed?'Assumption marked unverified':'Unsupported inference'}</span><p class="muted" style="margin-top:20px">Alternative explanation: a source record or cohort changed. Electrical headroom has not been established.</p><label for="review-note">Reviewer note — required</label><textarea id="review-note" class="field" rows="4" placeholder="Explain the evidence gap and next action.">${esc(reviewNote)}</textarea><p class="note">Avery Shah · fictional engineer role. Changes remain in this page only.</p><button class="button" id="mark-unverified">Mark assumption unverified</button><p id="review-status" class="status" role="status">${reviewed?'Local review recorded. Next task: obtain appropriate study evidence.':''}</p>`;}else{body.innerHTML=packetContent(reviewed,reviewNote||undefined)+`<button class="button" id="preview-packet">Open packet preview</button>`;}document.getElementById('source-pane').innerHTML=`<h3>Source & next action</h3><div class="disclosure">${selected} · Simulated</div><div class="packet-row"><span>Record snapshot</span><span>19 Oct 2026</span></div><div class="packet-row"><span>Prior snapshot</span><span>05 Oct 2026</span></div><div class="packet-row"><span>Tariff / rule date</span><span>Not configured</span></div><p style="margin-top:22px">${selected==='SYN-101'?'QUEUE-SYN-101, row 14. Expected study date changed.':'No detailed source row loaded for this view.'}</p><div class="uncertain">△ Available capacity is not established.</div><h4 style="margin-top:25px">Next action</h4><p>Obtain permissioned study material for independent engineer review.</p><p class="note">Reviewer decision: ${reviewed?'Unverified — local note retained':'Not recorded in this session'}</p><a class="text-link" href="/methodology">Read the methodology ↗</a>`;}
function baseRoute(){const p=decodeURIComponent(location.pathname).replace(/\/$/,'')||'/';if(p==='/sign-in'||p==='/access-help')return {title:'Workspace access',html:accessPage(p==='/access-help')};if(p==='/contact'||p==='/request-demo')return {title:p==='/contact'?'Contact':'Request walkthrough',html:intakeHero(p==='/contact'?'contact':'demo')};if(p==='/')return {title:'Keep the evidence connected',html:home()};if(p==='/products')return {title:'Five proposed products',html:pageHero('Products','Five specific jobs.<br>One evidence language.','Queue changes, site evidence, application preflight, study comparison and portfolio milestones. Each offer is separately scoped and quoted.')+`<section class="content-section"><div class="wrap">${productRows()}</div></section>`+closing()};const product=products.find(x=>p==='/products/'+x.id);if(product)return {title:product.name,html:productPage(product)};if(p==='/pricing')return {title:'Proposed pricing',html:pricing()};if(p==='/pilot')return {title:'Two-site evaluation',html:pilotPage()};if(p==='/platform')return {title:'Evidence platform',html:editorial('Platform','A connected record.<br>A human-owned decision.','Source evidence, exceptions, reviewer actions and exportable packets share one case ID.','flow',[['Observe before interpreting','Each input has a source reference, snapshot date, retrieval time and missingness. Observation and analyst interpretation are separate.',source()],['Review with the unknowns intact','Human reviewers own consequential decisions. Alternative explanations and unresolved assumptions remain visible.',comparison()],['Keep the record portable','The packet export is reversible and retains labels, sources, uncertainty and the next action.',packet()]])+closing()};if(p==='/why-interconnecttrack')return {title:'Why InterConnectTrack',html:editorial('Why InterConnectTrack','Fragmented evidence.<br>Consequential decisions.','Queue updates, tariffs and study assumptions can move at different times. A defensible decision needs more than another snapshot.','docs',[['The current substitutes matter','Utility portals, consultants, spreadsheet trackers and power-system studies already support this work. GridUnity provides interconnection workflows; Pearl Street provides grid-analysis modeling. InterConnectTrack’s proposed advantage remains unproven.',`<div class="source-doc"><h3>A focused hypothesis</h3><p>Source-linked packets may improve developer triage if engineers find them useful against their historical workflow.</p><a href="https://www.gridunity.com/" target="_blank" rel="noopener">GridUnity ↗</a><br><a href="https://pearlstreettechnologies.com/" target="_blank" rel="noopener">Pearl Street ↗</a></div>`],['Prove usefulness before expanding','Begin with a paid, permissioned, retrospective evaluation. Count distinct budget owners, named operators, authorized datasets and paid commitments separately.',pilotVisual()]])};if(p==='/solutions')return {title:'Developer workflows',html:pageHero('Use cases','Built around<br>the next handoff.','The first accountable buyer is a US renewable or storage developer’s interconnection director. Operators, engineers and data owners have different jobs.')+`<section class="content-section"><div class="wrap">${usecases.map((u,i)=>`<div class="content-section"><div class="usecase-view">${usecaseView(i)}</div></div>`).join('')}</div></section>`};if(p.startsWith('/solutions/')&&['site-screening','application-review','portfolio-oversight'].includes(p.split('/').pop()))return {title:'Developer workflow',html:solutionPage(p.split('/').pop())};if(p==='/resources')return {title:'Resources',html:resourcesPage()};if(p==='/resources/evidence-packet')return {title:'Sample evidence packet',html:packetPage()};if(p==='/resources/sample-queue-brief')return {title:'Sample queue brief',html:editorial('Sample queue brief','A new date.<br>A cited observation.','SYN-101 · fixed synthetic snapshots · as-of 20 Oct 2026. This brief shows the difference between a sourced observation and an unsupported inference.','timeline',[['Observed change','The expected study milestone changed from 15 Dec 2026 to 12 Jan 2027 between fictional snapshots dated 05 and 19 Oct 2026. The original value is retained.',source()],['Interpretation remains open','A source-list position change from 14 to 12 does not establish priority, available capacity or a better project outcome. A record/cohort change is an alternative explanation.',comparison()],['Reviewer next action','Obtain appropriate study evidence. Mark the unsupported capacity assumption unverified. Do not advance an approval field.',`${link('/demo/review','Open the local reviewer demo')}`]])};if(p==='/resources/interconnection-process')return {title:'Interconnection process',html:editorial('Process context','Screening supports a decision.<br>A study has its own authority.','Developer-side evidence triage belongs within a larger engineering and utility process.','flow',[['A developer-side sequence','Site screening → application preparation → supplied study review → post-submission milestones. Different providers use different terms and tariff-specific procedures.',documents()],['Policy and queue context','FERC Order 2023 addresses interconnection process reforms. Berkeley Lab’s queue research documents the substantial proposed-project pipeline. Neither establishes that this product shortens approval time.','<div class="source-doc"><h3>Primary sources</h3><p><a href="https://www.ferc.gov/interconnection-reform" target="_blank" rel="noopener">FERC interconnection reform ↗</a></p><p><a href="https://emp.lbl.gov/queues" target="_blank" rel="noopener">Berkeley Lab queue research ↗</a></p></div>'],['Keep jurisdictions specific','The prototype has one synthetic example, not a real RTO workflow. Actual rules must be loaded, versioned and reviewed before a jurisdiction is demonstrated.',`${link('/data-coverage','View configured coverage')}`]])};if(p==='/methodology')return {title:'Methodology',html:editorial('Methodology','Keep observation, interpretation<br>and review distinct.','A source-linked case carries input timestamps, missingness, analyst annotations, alternative explanations and a reviewer decision.','source',[['Source handling','Preserve source URL/reference, published date, effective date, retrieved date and snapshot version separately. When dates are unavailable, state the missingness rather than inventing it.',documents()],['Exceptions are part of the output','A missing document, conflicting value or stale source remains visible. A packet must not silently convert uncertainty into a clean score.',comparison()],['Evaluate independently','Pre-register the baseline, evaluator, comparison method, observation window and failure threshold. Any unsourced capacity conclusion presented as authoritative is a failure.',pilotVisual()]])};if(p==='/data-coverage')return {title:'Data coverage',html:pageHero('Data coverage','Know what is loaded.<br>Know what is not.','The demo uses a small fixed synthetic event log and mock redacted documents. Production connectors are future work subject to permission.')+`<section class="content-section"><div class="wrap table-scroll"><table><thead><tr><th>Source / workflow</th><th>Status</th><th>Version / date</th><th>Boundary</th></tr></thead><tbody>${[['Synthetic queue log','Loaded demo','05 / 19 Oct 2026','Fixed invented records'],['Mock study summaries','Partial demo','As-of 20 Oct 2026','Missing evidence preserved'],['Tariff / jurisdiction rules','Not configured','No actual rule date','No jurisdiction-specific claims'],['Utility portals / production models','Not connected','N/A','Permission and integration review required']].map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div></section><section class="section"><div class="wrap split"><div><h2>Source access and control<br>are different boundaries.</h2><p>Queue cadence, confidential study models and tariff specificity constrain data. Dispatch, accredited engineering and ISO/utility approvals remain outside the product’s authority.</p></div>${documents()}</div></section>`};if(p==='/trust')return {title:'Trust and boundaries',html:editorial('Trust','A clear boundary<br>is part of the product.','The isolated prototype supports evidence exploration and local review. It does not operate physical assets or make authoritative grid decisions.','packet',[['Data access','Real records require the appropriate procurement, legal and data-owner permission. Do not upload sensitive records to this public-facing prototype. No upload is provided.',documents()],['Physical and decision authority','No dispatch. No interconnection approval. No ISO or utility study authority. Accredited engineering and external approvals remain outside the agent’s scope.',flow()],['Commercial and evidence limits','Long procurement cycles and consultant relationships are material barriers. Evidence for policy, queue context and named adjacent competitors is stronger than evidence for product accuracy or willingness to pay. No security certification or customer claim is made.',pilotVisual()]])};if(p==='/company')return {title:'Company',html:editorial('Company','A defensible record<br>for every proposed project.','InterConnectTrack is a research-stage concept in energy and industry, focused on developer-side interconnection evidence.','flow',[['Our mission','Help developer interconnection teams move from fragmented evidence to a defensible, human-approved decision, with provenance and explicit uncertainty.',source()],['What we are testing','Whether a source-linked packet improves triage beyond current spreadsheets and consultant workflows. No real customers, revenue, live integrations or measured savings are claimed.',comparison()],['Begin narrow. Expand on evidence.','Start per development team or project portfolio. Queue intelligence, diligence and consultant workflow are expansion hypotheses. Utility-side intake requires separate validation. Queue megawatts are not software TAM.',`${link('/contact','Start a conversation')}`]])};if(p==='/contact'||p==='/request-demo')return {title:p==='/contact'?'Contact':'Request walkthrough',html:pageHero(p==='/contact'?'Contact':'Guided walkthrough',p==='/contact'?'Start with the question<br>your team needs to answer.':'See the record.<br>Follow the review.','Tell us the role and workflow you want to explore. This prototype previews a request locally; it does not send a message.')+`<section class="content-section"><div class="wrap split"><div><h2>${p==='/contact'?'A considered first conversation.':'A focused walkthrough.'}</h2><p>Explore the queue timeline, two-site evidence, missing-document checklist, scenario assumptions and portfolio milestones.</p><p class="note">Utility/ISO enquiries are kept separate from developer pilot demand. No dataset or confidential document is requested through this form.</p>${documents()}</div><div class="form-panel">${formHtml(p==='/contact'?'contact':'demo')}</div></div></section>`};if(p==='/request-received')return {title:'Request preview',html:pageHero('Local preview','Your request was<br>not sent.','This is the prototype confirmation state. No personal information was transmitted, saved or added to a mailing list.')+`<section class="content-section"><div class="wrap"><p>A connected intake and human-reviewed permission process are required before collecting real enquiries.</p>${link('/demo','Explore the synthetic demo')}</div></section>`};if(p==='/sign-in'||p==='/access-help')return {title:'Workspace access',html:`<section class="section"><div class="wrap auth-layout"><div><div class="breadcrumbs"><a href="/">Home</a> / Workspace access</div>${kick('Invited-workspace concept')}<h1>${p==='/sign-in'?'A considered place<br>for the next review.':'Workspace access<br>starts with an invitation.'}</h1><p class="muted">Authentication is not connected in this prototype. Explore the synthetic workspace without entering credentials.</p><div class="actions">${link('/demo','Enter the synthetic demo')}</div><p class="note">No password, SSO or live account is requested.</p><a href="${p==='/sign-in'?'/access-help':'/contact'}" class="text-link">${p==='/sign-in'?'Access help':'Contact for access context'} ↗</a></div><div class="auth-art" role="img" aria-label="Architectural illustration of fictional energy sites"></div></div></section>`};if(p.startsWith('/legal/')||p==='/accessibility'){let slug=p.split('/').pop();const legal={privacy:['Privacy for this prototype','Forms validate in your browser only. They do not transmit or persist contact information. Demo review state exists only in page memory and is cleared when the page reloads.','No real project uploads or connected databases are provided. Local downloads are initiated by the visitor and retain synthetic labels.','No analytics or advertising scripts have been added. The hosting provider may process ordinary request metadata under its own policies. Before a production intake is enabled, this notice must identify its operator, processors, retention and deletion channel.'],terms:['Prototype terms and limitations','This is a research-stage concept, not an operating interconnection service. Synthetic examples are for evaluation of interface and workflow only.','Do not rely on any fixture as grid capacity, study priority, a feasible site, a utility approval or an engineering conclusion. Use of real records requires a separate permissioned agreement.','Brand/domain ownership and legal terms require owner verification before commercial launch. No prices here are accepted market rates or active offers.'],cookies:['Cookies and local state','The application does not set cookies, use browser storage, or load analytics. Demo state is kept in memory for the current page.','The hosting platform may use its own authentication or infrastructure cookies. Those are outside this prototype’s application code.','A future analytics deployment must disclose its actual storage and honor appropriate consent and deletion requests.'],accessibility:['An accessible path through the evidence','The prototype includes keyboard focus styles, labeled controls, native scrolling, readable source labels and reduced-motion states.','The long scroll story has skip and view-all controls. On mobile and short screens, complete states are stacked rather than pinned.','These are implemented design intentions, not a claim of certified conformance. Report an issue through the local contact-request preview; no message is sent until a real intake is connected.']}[slug];if(legal)return {title:legal[0],html:pageHero(slug,legal[0],'A plain-language account of the current concept prototype.')+`<section class="content-section"><div class="wrap prose">${legal.slice(1).map((x,i)=>`<h3>0${i+1} / ${['Current behavior','Scope and limitations','Before production'][i]}</h3><p>${x}</p>`).join('')}<a href="/contact" class="text-link">Contact-request preview ↗</a></div></section>`};}
if(p==='/demo/pilot')return {title:'Synthetic pilot account',html:pageHero('Demo account','A proposed evaluation.<br>Not a revenue claim.','Alderline Development Demo is fictional. All names, roles, cases and commercial stages below are simulated.','pilot','/demo')+`<section class="content-section"><div class="wrap table-scroll"><table><tbody>${[['Budget owner','Morgan Hale · Interconnection Director'],['Operator','Riley Chen · Analyst'],['Engineer','Avery Shah · Reviewer'],['Data owner','Jordan Lee'],['Candidate sites','SYN-101 / SYN-102'],['Next tasks','Engineer review; request permissioned redacted study export'],['Stage','Qualification / conditional proposal — simulated'],['Proposed assessment','$4,000 — price test hypothesis'],['Paid SOW','Not signed'],['Revenue','None'],['Utility approval','Not granted']].map(([a,b])=>`<tr><th>${a}</th><td>${b}</td></tr>`).join('')}</tbody></table></div></section>`};if(p==='/demo'||p.startsWith('/demo/')){if(p.includes('/comparison')||p==='/demo/compare')demoTab='comparison';if(p.includes('/review'))demoTab='review';if(p.includes('/packet'))demoTab='packet';if(p.includes('SYN-102'))selected='SYN-102';return {title:'Synthetic evidence workbench',html:demoPage(),demo:true}}return {title:'Page not found',html:`<section class="error-page wrap">${kick('404 / A missing reference')}<h1>This page isn’t in the record.</h1><p>Return to the project story, inspect the five products or open the synthetic demo.</p><div class="actions" style="justify-content:center">${link('/','Home')}${link('/products','Products',true)}${link('/demo','Synthetic demo',true)}</div></section>`};}
function route(){const r=baseRoute(),path=location.pathname.replace(/\/$/,'')||'/';if(path==='/'||r.demo)return r;const product=products.find(p=>path==='/products/'+p.id);const family=product?product.id:path.startsWith('/solutions')?'solutions':path.startsWith('/resources')?'resources':path.startsWith('/legal')||path==='/trust'||path==='/accessibility'?'trust':path==='/company'||path==='/why-interconnecttrack'?'company':path==='/pilot'||path==='/contact'||path==='/request-demo'?'intake':'platform';return {...r,html:`<div class="secondary-page theme-${family}">${r.html}${path==='/company'?fundingSection():''}</div>`}}
const page=route();document.title=page.title+' — InterConnectTrack';document.getElementById('app').innerHTML=header()+`<main id="main" ${page.demo?'class="workbench-main"':''}>${page.html}</main>`+footer();
const motion=matchMedia('(prefers-reduced-motion: reduce)');
const mobileBtn=document.querySelector('.mobile-toggle');mobileBtn.addEventListener('click',()=>{const open=mobileBtn.getAttribute('aria-expanded')!=='true';mobileBtn.setAttribute('aria-expanded',String(open));mobileBtn.setAttribute('aria-label',open?'Close navigation':'Open navigation');mobileBtn.textContent=open?'×':'☰';document.querySelector('.mobile-nav').classList.toggle('open',open);document.body.classList.toggle('menu-open',open)});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){document.querySelectorAll('.menu-group[open]').forEach(x=>x.open=false);if(mobileBtn.getAttribute('aria-expanded')==='true'){mobileBtn.click();mobileBtn.focus()}}});document.addEventListener('click',e=>{document.querySelectorAll('.menu-group[open]').forEach(x=>{if(!x.contains(e.target))x.open=false})});
if(!window.gsap&&'IntersectionObserver' in window&&!motion.matches){document.documentElement.classList.add('js-motion');const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('is-visible');observer.unobserve(e.target)}}),{threshold:.08});document.querySelectorAll('.reveal').forEach(e=>observer.observe(e));}
const steps=[...document.querySelectorAll('[data-step]')];let raf=0,all=false,active=-1;
function syncStory(){raf=0;if(!steps.length||all||motion.matches||innerWidth<901||innerHeight<701||document.hidden)return;let index=0;steps.forEach((s,i)=>{if(s.getBoundingClientRect().top<innerHeight*.5)index=i});if(index===active)return;active=index;document.querySelectorAll('[data-scene]').forEach((e,i)=>{e.hidden=i!==index;if(i===index)document.dispatchEvent(new CustomEvent('ict:chapter-change',{detail:{panel:e,direction:'forward'}}))});document.querySelectorAll('[data-go]').forEach((e,i)=>{if(i===index)e.setAttribute('aria-current','step');else e.removeAttribute('aria-current')})}
function schedule(){if(!raf&&!document.hidden)raf=requestAnimationFrame(syncStory)}
if(steps.length){addEventListener('scroll',schedule,{passive:true});addEventListener('resize',schedule,{passive:true});document.getElementById('all-states').addEventListener('click',e=>{all=!all;document.getElementById('story').classList.toggle('all-scenes',all);e.currentTarget.setAttribute('aria-pressed',String(all));e.currentTarget.textContent=all?'Return to scroll story':'View all states / pause motion';schedule()});syncStory()}
document.addEventListener('visibilitychange',()=>{if(document.hidden&&raf){cancelAnimationFrame(raf);raf=0}else schedule()});
document.querySelectorAll('[data-usecase]').forEach(b=>{b.addEventListener('click',()=>{const i=Number(b.dataset.usecase);document.querySelectorAll('[data-usecase]').forEach(x=>x.setAttribute('aria-selected',String(x===b)));const panel=document.getElementById('use-panel');panel.innerHTML=usecaseView(i);panel.setAttribute('aria-labelledby',b.id)});b.addEventListener('keydown',e=>{if(['ArrowRight','ArrowLeft'].includes(e.key)){e.preventDefault();const i=(Number(b.dataset.usecase)+(e.key==='ArrowRight'?1:3))%4;const n=document.getElementById('use-tab-'+i);n.focus();n.click()}})});
document.querySelectorAll('.local-form').forEach(f=>{const show=n=>{f.dataset.intakeStep=String(n);f.querySelectorAll('[data-form-step]').forEach(el=>el.hidden=Number(el.dataset.formStep)!==n);f.querySelector('.form-step-count').textContent=n===1?'01 / 02':'02 / 02';f.querySelector('.form-step-name').textContent=n===1?'Your team':'Evaluation scope';f.querySelector(`[data-form-step="${n}"] input, [data-form-step="${n}"] select`)?.focus({preventScroll:true})};f.querySelector('.form-back').addEventListener('click',()=>show(1));f.addEventListener('submit',e=>{e.preventDefault();const step=Number(f.dataset.intakeStep);let first=null;f.querySelector(`[data-form-step="${step}"]`).querySelectorAll('[required]').forEach(input=>{const valid=input.checkValidity();input.setAttribute('aria-invalid',String(!valid));const error=document.getElementById(input.id+'-error');if(error)error.textContent=valid?'':input.type==='email'?'Enter a valid email address.':input.type==='checkbox'?'Please confirm permission to follow up.':'Complete this field.';if(!valid&&!first)first=input});if(first){first.focus();return}if(step===1){show(2);return}f.querySelector('.status').innerHTML='<strong>Request preview complete. Nothing was sent or stored.</strong><p>A connected, human-reviewed intake is needed to arrange an evaluation.</p>';f.reset();show(1);f.querySelector('.status').focus({preventScroll:true})})});
document.querySelectorAll('.access-form').forEach(f=>f.addEventListener('submit',e=>{e.preventDefault();const input=f.querySelector('input');if(!input.checkValidity()){input.setAttribute('aria-invalid','true');f.querySelector('.field-error').textContent='Enter a valid work email to preview this step.';input.focus();return}input.removeAttribute('aria-invalid');f.querySelector('.field-error').textContent='';f.querySelector('.status').innerHTML='<strong>Sign-in preview only.</strong><p>No email was sent. Authentication is not connected. You can open the synthetic workspace below.</p>';f.reset()}));
function exportPacket(){const lines=['INTERCONNECTTRACK','DEMO — SYNTHETIC DATA','NOT A GRID STUDY','SYN-101 Cedar Junction Storage / SYN-102 Mesa Reach Solar','As-of 20 October 2026','Observed: expected study date 15 December 2026 -> 12 January 2027','Source: fictional QUEUE-SYN-101 row 14; snapshots 05 and 19 October 2026','Missing: SYN-102 study material; evidence of electrical headroom','Alternative explanation: source record/cohort revision','Reviewer state: '+(reviewed?'Assumption marked unverified in local demo':'Further evidence required'), 'Reviewer note: '+(reviewNote||'Obtain appropriate study evidence before interpreting capacity.'),'Next action: obtain permissioned study evidence for independent engineer review.','No dispatch, external submission, engineering certification or connection approval.'];const blob=new Blob([lines.join('\n\n')],{type:'text/plain;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='InterConnectTrack-DEMO-review-packet.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
document.addEventListener('click',e=>{if(e.target.closest('[data-export]'))exportPacket();if(!page.demo)return;const c=e.target.closest('[data-case]');if(c){selected=c.dataset.case;updateDemo()}const tab=e.target.closest('[data-demo-tab]');if(tab){demoTab=tab.dataset.demoTab;updateDemo()}if(e.target.closest('[data-select-primary]')){selected='SYN-101';demoTab='evidence';updateDemo()}if(e.target.closest('#reset-demo')){selected='SYN-101';demoTab='evidence';reviewed=false;reviewNote='';document.getElementById('case-filter').value='all';document.querySelectorAll('.case-item').forEach(b=>b.hidden=false);document.getElementById('case-count').textContent='10 records · 2 blocked · 3 pending';updateDemo()}if(e.target.closest('[data-inspect-source]')){document.getElementById('source-pane').innerHTML=source()+`<p class="note">This source reference is invented for demonstration. It is not a real utility portal.</p>`;document.getElementById('source-pane').scrollIntoView({behavior:motion.matches?'auto':'smooth',block:'nearest'})}if(e.target.closest('#mark-unverified')){const field=document.getElementById('review-note');reviewNote=field.value.trim();if(!reviewNote){document.getElementById('review-status').textContent='Add a reviewer note explaining the gap and next action.';field.setAttribute('aria-invalid','true');field.focus();return}reviewed=true;updateDemo()}if(e.target.closest('#preview-packet')){document.getElementById('dialog-content').innerHTML=packetContent(reviewed,reviewNote||undefined);document.getElementById('packet-dialog').showModal()}if(e.target.closest('.dialog-close'))document.getElementById('packet-dialog').close()});
if(page.demo){updateDemo();document.getElementById('case-filter').addEventListener('change',e=>{let count=0;document.querySelectorAll('.case-item').forEach(b=>{const c=cases.find(c=>c.id===b.dataset.case);const show=e.target.value==='all'||c.status===e.target.value;b.hidden=!show;if(show)count++});document.getElementById('case-count').textContent=count+' matching synthetic records';});}

// Shared, progressively enhanced artifact motion. Every data value stays fixed.
function enhanceArtifacts(root=document){root.querySelectorAll('.timeline-visual,.evidence-console,.packet-console,.source-doc,.flow-console,.scenario-console,.milestone-console').forEach(el=>{if(el.dataset.observed)return;el.dataset.observed='true';if(window.gsap||motion.matches||!('IntersectionObserver' in window)){el.classList.add('artifact-visible');return}artifactObserver.observe(el)});root.querySelectorAll('.button').forEach(b=>{if(b.querySelector('.button-label'))return;const old=b.querySelector('.arrow');if(old)old.remove();const label=document.createElement('span');label.className='button-label';while(b.firstChild)label.appendChild(b.firstChild);b.append(label);b.insertAdjacentHTML('beforeend',arrow())});}
const artifactObserver='IntersectionObserver' in window?new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('artifact-visible');artifactObserver.unobserve(e.target)}}),{threshold:.16}):null;
enhanceArtifacts();
document.addEventListener('click',e=>{const b=e.target.closest('[data-product]');if(b){const explorer=b.closest('.product-explorer');explorer.querySelectorAll('[data-product]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));const preview=explorer.querySelector('.product-preview');preview.innerHTML=productPreview(Number(b.dataset.product));enhanceArtifacts(preview)}if(e.target.closest('[data-usecase],[data-demo-tab],[data-case],[data-inspect-source]'))requestAnimationFrame(()=>enhanceArtifacts());});
document.querySelectorAll('.closing').forEach(el=>{el.addEventListener('pointermove',e=>{if(motion.matches||e.pointerType==='touch')return;const r=el.getBoundingClientRect();el.style.setProperty('--drift-x',((e.clientX-r.left)/r.width-.5)*18+'px');el.style.setProperty('--drift-y',((e.clientY-r.top)/r.height-.5)*12+'px')},{passive:true});el.addEventListener('pointerleave',()=>{el.style.setProperty('--drift-x','0px');el.style.setProperty('--drift-y','0px')})});

// Natural-scroll chapters: sticky on roomy screens, complete stacked chapters on compact screens.
const journeys=[...document.querySelectorAll('[data-journey]')].map(root=>({root,pin:root.querySelector('.journey-pin'),panels:[...root.querySelectorAll('[data-chapter]')],buttons:[...root.querySelectorAll('[data-journey-to]')],index:-1,expanded:false,sticky:false}));
function setJourney(j,index){if(j.index===index)return;j.root.dataset.direction=index<j.index?'backward':'forward';j.index=index;j.root.dataset.active=String(index);j.buttons.forEach((b,i)=>b.setAttribute('aria-current',i===index?'step':'false'));j.panels.forEach((panel,i)=>{panel.classList.toggle('chapter-active',i===index);panel.inert=j.sticky&&i!==index;if(j.sticky&&i!==index)panel.setAttribute('aria-hidden','true');else panel.removeAttribute('aria-hidden')});j.root.querySelector('.journey-counter').textContent=String(index+1).padStart(2,'0')+' / '+String(j.panels.length).padStart(2,'0');if(j.sticky){const panel=j.panels[index];document.dispatchEvent(new CustomEvent('ict:chapter-change',{detail:{panel,direction:j.root.dataset.direction}}));enhanceArtifacts(panel);panel.querySelectorAll('[data-observed]').forEach(el=>el.classList.add('artifact-visible'));}}
function layoutJourneys(){journeys.forEach(j=>{j.sticky=!motion.matches&&!j.expanded&&innerWidth>=700&&innerHeight>=560;j.root.classList.toggle('journey-sticky',j.sticky);j.root.classList.toggle('journey-stacked',!j.sticky);j.index=-1;j.root.querySelector('.journey-hint').textContent=j.sticky?'Scroll down to advance · up to return':'Follow each step ↓';setJourney(j,0)});updateJourneys()}
let journeyFrame=0;
function updateJourneys(){journeyFrame=0;journeys.forEach(j=>{let index=0;if(j.sticky){const r=j.root.getBoundingClientRect(),travel=j.root.offsetHeight-j.pin.offsetHeight;const progress=Math.max(0,Math.min(1,(100-r.top)/Math.max(1,travel)));index=Math.min(j.panels.length-1,Math.floor(progress*j.panels.length));j.root.style.setProperty('--journey-progress',String(progress));}else{j.panels.forEach((p,i)=>{if(p.getBoundingClientRect().top<innerHeight*.5)index=i});j.root.style.setProperty('--journey-progress',String((index+1)/j.panels.length));}setJourney(j,index)})}
function queueJourney(){if(!journeyFrame)journeyFrame=requestAnimationFrame(updateJourneys)}
journeys.forEach(j=>{j.buttons.forEach((b,i)=>b.addEventListener('click',()=>{if(j.sticky){const start=j.root.getBoundingClientRect().top+scrollY-100,travel=j.root.offsetHeight-j.pin.offsetHeight;if(window.siteScroller)window.siteScroller.scrollTo(start+travel*(i+.5)/j.panels.length,{immediate:true});else window.scrollTo({top:start+travel*(i+.5)/j.panels.length,behavior:'instant'});updateJourneys();}else j.panels[i].scrollIntoView({behavior:motion.matches?'instant':'smooth',block:'start'});}));j.root.querySelector('.journey-mode').addEventListener('click',e=>{j.expanded=!j.expanded;e.currentTarget.setAttribute('aria-pressed',String(j.expanded));e.currentTarget.textContent=j.expanded?'Return to scroll story':'View all steps';layoutJourneys();j.root.scrollIntoView({behavior:'instant',block:'start'})});});
addEventListener('scroll',queueJourney,{passive:true});addEventListener('resize',layoutJourneys,{passive:true});motion.addEventListener('change',layoutJourneys);layoutJourneys();

